import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"12、【否】 坤下乾上","description":"周易尚氏学 - 12、【否】 坤下乾上","frontmatter":{"title":"12、【否】 坤下乾上","description":"周易尚氏学 - 12、【否】 坤下乾上"},"headers":[],"relativePath":"zh/classics/shangshi/017.md","filePath":"zh/classics/shangshi/017.md"}'),h={name:"zh/classics/shangshi/017.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_12、【否】-坤下乾上" tabindex="-1">12、【否】 坤下乾上 <a class="header-anchor" href="#_12、【否】-坤下乾上" aria-label="Permalink to “12、【否】 坤下乾上”">​</a></h1><p>阳上升。阴下降。乃阳即在上。阴即在下。愈去愈远。故天地不交而为否。否闭也。泰上六象传云其命乱也。言泰极反否。乃天地自然之命运。必至之理。非人力所能为。此曰否之匪人。仍其义也。阳往外而诎。阴来内而信。故不利君子贞。贞卜问。其以正为说者。无论若何斡旋。皆不能通。</p><p>彖曰。否之匪人。不利君子贞，大往小来。则是天地不交。而万物不通也。上下不交。而天下无邦也。内阴而外阳。内柔而外刚。内小人而外君子。小人道长。君子道消也。</p><p>天气本上腾而在外。地气本下降而在内。愈去愈远。故气不交。气不交故万物不通而死矣。坤为万物为邦国。乾上坤下。君民不亲。上下闭塞。而邦必乱。故曰无邦。否七月卦。阴长阳消。故曰小人道长。君子道消。</p><p>象曰。天地不交。否。君子以俭德辟难。不可荣以禄。</p><p>乾为德。俭约也。坤闭故曰俭德。言敛抑自守也。互巽为伏。故曰辟难。坤为患为难。言遁世不出。以避世难。乾为禄。艮为荣。巽伏故不可荣以禄位。言当否之时。遁人山林。高隐不出也。</p><p>初六。拔茅茹以其汇。征吉。亨。</p><p>阴皆有应。故辞与泰同。泰茅茹象。指应爻。此则用本象也。</p><h3 id="象曰。拔茅征吉。志在君也。" tabindex="-1">象曰。拔茅征吉。志在君也。 <a class="header-anchor" href="#象曰。拔茅征吉。志在君也。" aria-label="Permalink to “象曰。拔茅征吉。志在君也。”">​</a></h3><p>坤为志。乾为君。志在君。言上应四也。</p><p>六二。苞承。小人吉。大人否亨。</p><p>苞今本作包。依唐石经及释文。下同。包苞古通用。禹贡。草木渐包。注包丛生。释文。字亦作苞。是包苞古不分。尔雅释言云苞稹也。疏。孙炎曰。物丛生曰苞。诗唐风。集于苞栩。亦以苞为丛。是苞有多意。众义。坤为众。苞承者。言下三爻皆承阳有应也。小人谓二。二得中有应。故小人吉。凡阴得阳应必吉。阳得阴应不皆吉。而否卦阳气上腾。不能下降。故大人否亨。大人谓五。否不。言五虽得二应而不亨也。朱升释承为脀。卦既无此象。荀爽谓二为四所包。朱震谓二为五所包。夫四五若能下施包二。则大人不否亨矣。非也。</p><h3 id="象曰。大人否亨。不乱群也。" tabindex="-1">象曰。大人否亨。不乱群也。 <a class="header-anchor" href="#象曰。大人否亨。不乱群也。" aria-label="Permalink to “象曰。大人否亨。不乱群也。”">​</a></h3><p>坤众放曰群。坤为乱。乱杂也。不乱群。言五不能下施应二。俾天地相杂也。故否亨。虞翻谓坤三阴。乱弒君。大人不从。故不乱群。岂知不乱群。即仍天地不交之义。言五不能交二也。群义即释苞义也。</p><p>六三。苞羞。</p><p>此苞字与上同义。仍坤众坤群象也。羞。说文进献也。左传隐三年。润溪沼沚之毛。可荐于鬼神。可羞于王公。杜注羞进也。国语楚语下。于是乎每朝设脯一束。以羞子文。注亦作进。苞羞者众进也。否本阴长之卦。故群进而消阳也。</p><h3 id="象曰。苞羞。位不当也。" tabindex="-1">象曰。苞羞。位不当也。 <a class="header-anchor" href="#象曰。苞羞。位不当也。" aria-label="Permalink to “象曰。苞羞。位不当也。”">​</a></h3><p>六三不当位。进至于四。或与上相上下。则当位矣。言所以进者。以不当位也。释苞羞之故也。自荀爽释为羞耻。朱升释为膳羞。位不当之义。皆莫知所指矣。</p><p>九四。有命。无咎。畴离祉。</p><p>命。说文使也。广韵召也。有命言有所使命也。巽为命。周语襄王锡晋文公命。盖四履群阴之上。万民(坤为民)顺承。故有所锡命。四不当位。宜有咎。得群阴使命。故无咎。颐上九云。利涉大川。与此义同也。畴俦同。荀子劝学篇云。草木畴生。注畴同俦。前汉韩信传。其畴十三人。义亦同俦。俦众也。下坤为众。离附着。祉福。畴离祉者。言众阴同附阳。得主而受福也。孔疏训畴为匹。匹谓初。言初得阳应而受福。然象释曰志行。荀爽谓志行于群阴。固统三阴言。不专指初也。</p><h3 id="象曰。有命无咎。志行也。" tabindex="-1">象曰。有命无咎。志行也。 <a class="header-anchor" href="#象曰。有命无咎。志行也。" aria-label="Permalink to “象曰。有命无咎。志行也。”">​</a></h3><p>四履重阴。得行其志。故曰志行。</p><p>九五。体否。大人吉。其亡其亡。系于苞桑。</p><p>说文人依木则休。休者憩息也。休否者。言当否之时。而休息以俟也。盖初四三上相上下。则既济成。五当位居中。宜静俟也。旧解释为休美。与其亡义背。似非也。九五为大人。故曰大人吉。九五巽体。巽为桑。坤为多。故曰苞桑。陆绩京氏易传注云。苞桑则丛桑也。巽为绳。为系。故曰系于苞桑。乃巽为陨落。五虽居中得正。而风陨在下。故有其亡之惧。盖系在大木。方能巩固。桑而丛生。其柔可知。系于柔木。其危可知。其亡其亡。系于苞桑者。言时时虑亡。如系于苞桑之不足恃也。王陶庐云。唐石经初刻作包。后增改作苞。按禹贡草木渐包。传释为丛生。仍与苞同。自风陨象失传。后儒不知危亡之故。在五履巽。于是旧解皆以坚固为说。遂与易象不协矣。</p><h3 id="象曰。大人之吉。位正当也。" tabindex="-1">象曰。大人之吉。位正当也。 <a class="header-anchor" href="#象曰。大人之吉。位正当也。" aria-label="Permalink to “象曰。大人之吉。位正当也。”">​</a></h3><p>五位尊而中正。故曰位当。</p><p>上九。倾否。先否后喜。</p><p>侯果曰。倾覆也。上应在三。三巽为陨落。故曰倾否。言倾否而出之尽也。然当未覆之先。则仍否也。故曰先否。上反下则成震。震为乐为后。故曰后喜。</p><h3 id="象曰。否终则倾。何可长也。" tabindex="-1">象曰。否终则倾。何可长也。 <a class="header-anchor" href="#象曰。否终则倾。何可长也。" aria-label="Permalink to “象曰。否终则倾。何可长也。”">​</a></h3><p>否终则倾。言否终则泰复。不能长否。按否泰云。大小往来。无平不陂。无往不复。终则曰城复于隍。其命乱也。否则曰否之匪人。皆言天地否泰之运。循环往来。自然如此。不假人为。为上经天地水火之枢纽。明天道本如斯。不可易也。至下经第十卦之损益。则曰损益盈虚。与时偕行。曰损刚益柔。曰损下益上。损上益下。曰见善则迁。有过则改。所言皆履世之大经。修治之极轨。无丝毫委心任运之意。以为咸恒既未济之枢纽。明人事宜如斯也。尽人事。听天命。斯学易之功也。</p>',30)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
